result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "app/main.py", "content": """"Notes REST API: FastAPI + stdlib sqlite3, no ORM.

Every error response uses the envelope {"error": {"code": ..., "message": ...}}.
"""
from datetime import datetime, timezone
from typing import Any

from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

from .db import get_db

app = FastAPI(title="Notes API")


# --------------------------------------------------------------------------
# Error envelope helpers / handlers
# --------------------------------------------------------------------------

class NotFoundError(HTTPException):
    def __init__(self, message: str = "Note not found"):
        super().__init__(status_code=404, detail=message)


def error_response(status_code: int, code: str, message: str) -> JSONResponse:
    return JSONResponse(
        status_code=status_code,
        content={"error": {"code": code, "message": message}},
    )


@app.exception_handler(NotFoundError)
async def not_found_handler(request: Request, exc: NotFoundError) -> JSONResponse:
    return error_response(404, "not_found", str(exc.detail))


@app.exception_handler(RequestValidationError)
async def validation_error_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    return error_response(422, "validation_error", str(exc.errors()))


@app.exception_handler(Exception)
async def unhandled_error_handler(request: Request, exc: Exception) -> JSONResponse:
    return error_response(500, "internal_error", "Internal server error")


# --------------------------------------------------------------------------
# Schemas
# --------------------------------------------------------------------------

class NoteCreate(BaseModel):
    title: str = Field(min_length=1, max_length=200)
    body: str = ""


class NoteUpdate(BaseModel):
    title: str | None = Field(default=None, min_length=1, max_length=200)
    body: str | None = None


class NoteOut(BaseModel):
    id: int
    title: str
    body: str
    created_at: str
    updated_at: str


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def row_to_dict(row: Any) -> dict[str, Any]:
    return {
        "id": row["id"],
        "title": row["title"],
        "body": row["body"],
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
    }


# --------------------------------------------------------------------------
# Routes
# --------------------------------------------------------------------------

@app.post("/notes", status_code=201, response_model=NoteOut)
def create_note(payload: NoteCreate, db=Depends(get_db)) -> dict[str, Any]:
    now = utc_now()
    cur = db.execute(
        "INSERT INTO notes (title, body, created_at, updated_at) VALUES (?, ?, ?, ?)",
        (payload.title, payload.body, now, now),
    )
    db.commit()
    row = db.execute("SELECT * FROM notes WHERE id = ?", (cur.lastrowid,)).fetchone()
    return row_to_dict(row)


@app.get("/notes", response_model=list[NoteOut])
def list_notes(db=Depends(get_db)) -> list[dict[str, Any]]:
    rows = db.execute("SELECT * FROM notes ORDER BY id").fetchall()
    return [row_to_dict(r) for r in rows]


@app.get("/notes/{note_id}", response_model=NoteOut)
def get_note(note_id: int, db=Depends(get_db)) -> dict[str, Any]:
    row = db.execute("SELECT * FROM notes WHERE id = ?", (note_id,)).fetchone()
    if row is None:
        raise NotFoundError()
    return row_to_dict(row)


@app.put("/notes/{note_id}", response_model=NoteOut)
def update_note(note_id: int, payload: NoteUpdate, db=Depends(get_db)) -> dict[str, Any]:
    row = db.execute("SELECT * FROM notes WHERE id = ?", (note_id,)).fetchone()
    if row is None:
        raise NotFoundError()
    title = payload.title if payload.title is not None else row["title"]
    body = payload.body if payload.body is not None else row["body"]
    db.execute(
        "UPDATE notes SET title = ?, body = ?, updated_at = ? WHERE id = ?",
        (title, body, utc_now(), note_id),
    )
    db.commit()
    updated = db.execute("SELECT * FROM notes WHERE id = ?", (note_id,)).fetchone()
    return row_to_dict(updated)


@app.delete("/notes/{note_id}", status_code=204)
def delete_note(note_id: int, db=Depends(get_db)) -> None:
    cur = db.execute("DELETE FROM notes WHERE id = ?", (note_id,))
    db.commit()
    if cur.rowcount == 0:
        raise NotFoundError()
